export function makePinnedLookup(pinIp: string): LookupFunction {
  const fam = isIP(pinIp) === 6 ? 6 : 4;
  const lookup = (_host: string, options: { all?: boolean } | undefined, cb: (...a: unknown[]) => void): void => {
