run<T>(task: () => Promise<T>): Promise<T | undefined> {
  const gen = this.gen;
  const prev = this.tail;
  const p = (async (): Promise<T | undefined> => {
    await prev.catch(() => undefined);
    if (gen !== this.gen) return undefined; // cancelled by a clear() while we waited
    return task();
  })();
  this.tail = p.then(
    () => undefined,
    () => undefined,
  );
  return p;
}

export async function withProactiveLock<T>(
  session: Session,
  fn: () => Promise<T>,
): Promise<T | null> {
  if (inFlight.has(session.id)) return null;
  if (session.activeTurn !== null) return null;
  if (isDreaming()) return null;
  if (!proactiveEnabled()) return null;
  inFlight.add(session.id);
  try {
    return await fn();
  } finally {
    inFlight.delete(session.id);
  }
}

